#!/usr/bin/env python3
"""Synthetic dispatch tests for researchctld direct C/D and delegated A/B.

``dispatch()`` is exercised with in-memory fakes for ResearchDB,
AuthorityStore and daemon_context, so:
  * no production daemon is started (no Server/Handler/Unix socket);
  * no production (or any) database is opened -- the apsw stub from the
    harness fails loudly on any accidental connection, and the fakes record
    that no research.sqlite file is ever created.

The tests pin the current v3 wiring:
  * direct C/D routes to AuthorityStore.register_amendment_direct with the
    ctx built from (peer_pid, peer_uid) and a daemon-side fail-closed guard
    for missing/non-string/non-empty fields;
  * delegated A/B routes to AuthorityStore.register_amendment;
  * C/D on the delegated wire is passed through and rejected by the store
    (ROOT_CANNOT_REGISTER_C_OR_D) -- CLI choices are the parser-level gate;
  * the v3 schema gate runs before any authority command and fails closed
    when schema_version() reports a non-v3 database.
"""

from __future__ import annotations

import json
import tempfile
from pathlib import Path
from typing import Any, Callable

import synthetic_harness as harness

harness.install()

from app_v2.p5_infra import researchctld  # noqa: E402
from app_v2.p5_infra.authority_store import (  # noqa: E402
    AMENDMENT_A_SHA256,
    AMENDMENT_B_SHA256,
    AMENDMENT_C_SHA256,
)
from app_v2.p5_infra.research_db import FailClosed  # noqa: E402

D_HASH = "d" * 64

PASSED: list[str] = []
FAILED: list[tuple[str, str]] = []
TESTS: list[tuple[str, Callable[[], None]]] = []


def test(fn: Callable[[], None]) -> Callable[[], None]:
    TESTS.append((fn.__name__, fn))
    return fn


class Ctx:
    """Shape-compatible stand-in for authority_runtime.DaemonContext."""

    def __init__(self, uid: int, session: str, seq: int = 1) -> None:
        self.peer_uid = uid
        self.session_id = session
        self.recorded_at = "2026-08-13T00:00:00Z"
        self.ledger_sequence = seq

    def validate(self) -> "Ctx":
        return self


class FakeDB:
    instances: list["FakeDB"] = []
    fail_schema: Exception | None = None

    def __init__(self, root: str | Path) -> None:
        self.root = Path(root)
        self.schema_checks = 0
        FakeDB.instances.append(self)

    def schema_version(self) -> int:
        self.schema_checks += 1
        if FakeDB.fail_schema is not None:
            raise FakeDB.fail_schema
        return 3

    def verify(self) -> dict[str, Any]:
        raise AssertionError("dispatch tests must never reach DB verify")


class FakeAuthority:
    instances: list["FakeAuthority"] = []
    behavior: dict[str, Exception] = {}

    def __init__(self, db_path: str | Path) -> None:
        self.db_path = Path(db_path)
        self.calls: list[tuple[Any, ...]] = []
        FakeAuthority.instances.append(self)

    def _record(self, name: str, *args: Any) -> dict[str, Any]:
        self.calls.append((name,) + args)
        if name in FakeAuthority.behavior:
            raise FakeAuthority.behavior[name]
        return {"status": "PASS", "command": name}

    def register_amendment_direct(
        self, amendment_id: str, amendment_sha256: str,
        producer_session_id: str, ctx: Ctx | None,
    ) -> dict[str, Any]:
        return self._record(
            "register_amendment_direct", amendment_id,
            amendment_sha256, producer_session_id, ctx,
        )

    def register_amendment(
        self, delegation_id: str, amendment_id: str,
        amendment_sha256: str, ctx: Ctx | None,
    ) -> dict[str, Any]:
        return self._record(
            "register_amendment", delegation_id, amendment_id,
            amendment_sha256, ctx,
        )

    def proposal(self, *args: Any) -> dict[str, Any]:
        raise AssertionError("unexpected authority command: proposal")

    def transition(self, *args: Any) -> dict[str, Any]:
        raise AssertionError("unexpected authority command: transition")

    def register_delegation(self, *args: Any) -> dict[str, Any]:
        raise AssertionError("unexpected authority command: register_delegation")

    def redeem(self, *args: Any) -> dict[str, Any]:
        raise AssertionError("unexpected authority command: redeem")

    def revoke(self, *args: Any) -> dict[str, Any]:
        raise AssertionError("unexpected authority command: revoke")


class Patch:
    """Swap researchctld globals for fakes and restore them afterwards."""

    def __init__(self, tmp: str) -> None:
        self.tmp = Path(tmp)
        self.context_calls: list[tuple[int, int]] = []
        self._saved = {
            "ROOT": researchctld.ROOT,
            "ResearchDB": researchctld.ResearchDB,
            "AuthorityStore": researchctld.AuthorityStore,
            "daemon_context": researchctld.daemon_context,
        }

    def fake_context(self, peer_pid: int, peer_uid: int) -> Ctx:
        self.context_calls.append((peer_pid, peer_uid))
        return Ctx(peer_uid, f"session-{peer_pid}", seq=peer_pid)

    def __enter__(self) -> "Patch":
        researchctld.ROOT = self.tmp
        researchctld.ResearchDB = FakeDB
        researchctld.AuthorityStore = FakeAuthority
        researchctld.daemon_context = self.fake_context
        return self

    def __exit__(self, *exc: object) -> bool:
        for key, value in self._saved.items():
            setattr(researchctld, key, value)
        return False


def fresh() -> None:
    FakeDB.instances = []
    FakeAuthority.instances = []
    FakeAuthority.behavior = {}
    FakeDB.fail_schema = None


def expect_fail_closed(code: str, fn: Callable[[], Any]) -> None:
    try:
        fn()
    except FailClosed as exc:
        assert str(exc) == code, f"expected {code!r}, got {str(exc)!r}"
        return
    raise AssertionError(f"expected FailClosed({code!r})")


# --------------------------------------------------------------------------
# direct C/D routing
# --------------------------------------------------------------------------

@test
def direct_c_routed_to_store() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td) as patch:
        result = researchctld.dispatch(
            {
                "command": "amendment-register-direct",
                "amendment_id": "C",
                "amendment_sha256": AMENDMENT_C_SHA256,
                "producer_session_id": "producer-session",
            },
            peer_uid=9001,
            peer_pid=1234,
        )
        assert result == {"status": "PASS", "command": "register_amendment_direct"}
        db = FakeDB.instances[-1]
        assert db.root == Path(td)
        assert db.schema_checks == 1
        authority = FakeAuthority.instances[-1]
        assert authority.db_path == Path(td) / "research.sqlite"
        name, amendment_id, digest, producer, ctx = authority.calls[0]
        assert name == "register_amendment_direct"
        assert amendment_id == "C"
        assert digest == AMENDMENT_C_SHA256
        assert producer == "producer-session"
        assert isinstance(ctx, Ctx)
        assert ctx.peer_uid == 9001
        assert ctx.session_id == "session-1234"
        assert patch.context_calls == [(1234, 9001)]
        assert list(Path(td).rglob("*")) == []  # no DB file created


@test
def direct_d_routed_to_store() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        result = researchctld.dispatch(
            {
                "command": "amendment-register-direct",
                "amendment_id": "D",
                "amendment_sha256": D_HASH,
                "producer_session_id": "producer-session",
            },
            peer_uid=9001,
            peer_pid=1234,
        )
        assert result == {"status": "PASS", "command": "register_amendment_direct"}
        call = FakeAuthority.instances[-1].calls[0]
        assert call[1] == "D" and call[2] == D_HASH and call[3] == "producer-session"


@test
def direct_store_rejections_propagate() -> None:
    for code in (
        "OWNER_CREDENTIAL_REQUIRED",
        "OWNER_SESSION_SEPARATION_FAILED",
        "DIRECT_OWNER_ONLY_C_OR_D",
        "AMENDMENT_ID_HASH_BINDING_MISMATCH",
        "C_FIRST_D_SECOND_REQUIRED",
    ):
        fresh()
        with tempfile.TemporaryDirectory() as td, Patch(td):
            FakeAuthority.behavior = {
                "register_amendment_direct": FailClosed(code),
            }
            expect_fail_closed(code, lambda: researchctld.dispatch(
                {
                    "command": "amendment-register-direct",
                    "amendment_id": "C",
                    "amendment_sha256": AMENDMENT_C_SHA256,
                    "producer_session_id": "producer-session",
                },
                peer_uid=9001,
                peer_pid=1234,
            ))


@test
def direct_missing_or_invalid_fields_fail_closed() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        cases = [
            {"command": "amendment-register-direct"},  # all three missing
            {"command": "amendment-register-direct", "amendment_id": "C"},
            {"command": "amendment-register-direct",
             "amendment_id": "C", "amendment_sha256": AMENDMENT_C_SHA256},
            {"command": "amendment-register-direct",
             "amendment_id": "C", "amendment_sha256": "",
             "producer_session_id": "producer-session"},
            {"command": "amendment-register-direct",
             "amendment_id": "C", "amendment_sha256": AMENDMENT_C_SHA256,
             "producer_session_id": None},
            {"command": "amendment-register-direct",
             "amendment_id": 7, "amendment_sha256": AMENDMENT_C_SHA256,
             "producer_session_id": "producer-session"},
        ]
        for request in cases:
            expect_fail_closed(
                "amendment-register-direct requires amendment_id, "
                "amendment_sha256, producer_session_id",
                lambda r=request: researchctld.dispatch(r, peer_uid=9001, peer_pid=1234),
            )
        assert FakeAuthority.instances[-1].calls == []


@test
def direct_peer_pid_minus_one_passes_none_ctx() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td) as patch:
        researchctld.dispatch(
            {
                "command": "amendment-register-direct",
                "amendment_id": "C",
                "amendment_sha256": AMENDMENT_C_SHA256,
                "producer_session_id": "producer-session",
            },
            peer_uid=9001,
            peer_pid=-1,
        )
        assert patch.context_calls == []
        assert FakeAuthority.instances[-1].calls[0][4] is None


# --------------------------------------------------------------------------
# delegated A/B routing
# --------------------------------------------------------------------------

@test
def delegated_a_routed_to_store() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        result = researchctld.dispatch(
            {
                "command": "amendment-register",
                "delegation_id": "root-delegation-1",
                "amendment_id": "A",
                "amendment_sha256": AMENDMENT_A_SHA256,
            },
            peer_uid=1001,
            peer_pid=4321,
        )
        assert result == {"status": "PASS", "command": "register_amendment"}
        call = FakeAuthority.instances[-1].calls[0]
        assert call[1] == "root-delegation-1"
        assert call[2] == "A"
        assert call[3] == AMENDMENT_A_SHA256
        assert call[4].peer_uid == 1001
        assert FakeDB.instances[-1].schema_checks == 1


@test
def delegated_b_routed_to_store() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        researchctld.dispatch(
            {
                "command": "amendment-register",
                "delegation_id": "root-delegation-1",
                "amendment_id": "B",
                "amendment_sha256": AMENDMENT_B_SHA256,
            },
            peer_uid=1001,
            peer_pid=4321,
        )
        call = FakeAuthority.instances[-1].calls[0]
        assert call[2] == "B" and call[3] == AMENDMENT_B_SHA256


@test
def delegated_cd_rejected_by_store() -> None:
    # The daemon passes C/D through on the delegated wire; the store is the
    # authoritative gate (ROOT_CANNOT_REGISTER_C_OR_D) and the CLI choices
    # are the parser-level gate.  Both layers must fail closed.
    for bad in ("C", "D"):
        fresh()
        with tempfile.TemporaryDirectory() as td, Patch(td):
            FakeAuthority.behavior = {
                "register_amendment": FailClosed("ROOT_CANNOT_REGISTER_C_OR_D"),
            }
            expect_fail_closed("ROOT_CANNOT_REGISTER_C_OR_D",
                               lambda b=bad: researchctld.dispatch(
                                   {
                                       "command": "amendment-register",
                                       "delegation_id": "root-delegation-1",
                                       "amendment_id": b,
                                       "amendment_sha256": AMENDMENT_C_SHA256,
                                   },
                                   peer_uid=1001,
                                   peer_pid=4321,
                               ))
            assert FakeAuthority.instances[-1].calls[0][2] == bad


# --------------------------------------------------------------------------
# schema gate and generic dispatch guards
# --------------------------------------------------------------------------

@test
def schema_gate_fails_closed_on_non_v3() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        FakeDB.fail_schema = FailClosed("unsupported schema metadata: []")
        for request in (
            {
                "command": "amendment-register-direct",
                "amendment_id": "C",
                "amendment_sha256": AMENDMENT_C_SHA256,
                "producer_session_id": "producer-session",
