        ):
            expect_fail_closed(
                "unsupported schema metadata: []",
                lambda r=request: researchctld.dispatch(r, peer_uid=9001, peer_pid=1234),
            )
        assert FakeAuthority.instances[-1].calls == []


@test
def negative_peer_uid_fails_before_any_construction() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        expect_fail_closed(
            "authenticated Unix peer identity is unavailable",
            lambda: researchctld.dispatch(
                {
                    "command": "amendment-register-direct",
                    "amendment_id": "C",
                    "amendment_sha256": AMENDMENT_C_SHA256,
                    "producer_session_id": "producer-session",
                },
                peer_uid=-1,
                peer_pid=1234,
            ),
