@test
def unknown_command_allowlisted() -> None:
    fresh()
    with tempfile.TemporaryDirectory() as td, Patch(td):
        expect_fail_closed(
            "daemon command is not allowlisted: bogus",
            lambda: researchctld.dispatch({"command": "bogus"}, peer_uid=9001, peer_pid=-1),
        )


# --------------------------------------------------------------------------

def main() -> bool:
    PASSED.clear()
    FAILED.clear()
    for name, fn in TESTS:
        try:
            fn()
        except SystemExit as exc:
            FAILED.append((name, f"SystemExit({exc.code})"))
            print("FAIL", name, f"SystemExit({exc.code})")
        except Exception as exc:
            FAILED.append((name, repr(exc)))
            print("FAIL", name, repr(exc))
        else:
            PASSED.append(name)
            print("PASS", name)
    print(json.dumps({
        "suite": "test_cli_dispatch_synthetic",
        "run": len(PASSED) + len(FAILED),
        "pass": len(PASSED),
        "fail": len(FAILED),
        "failures": FAILED,
    }, sort_keys=True))
    return not FAILED


if __name__ == "__main__":
    raise SystemExit(0 if main() else 1)

#!/usr/bin/env python3
"""Synthetic parser and wire-format tests for researchctl amendment commands.

Covers:
  * direct-owner C/D  -> ``amendment-register-direct`` (choices C|D,
    required --amendment-sha256 and --producer-session-id);
  * delegated A/B     -> ``amendment-register`` (choices A|B only, C/D must
    be rejected by argparse);
  * the JSON request built by ``daemon_request`` (transport-only flags
    --root/--socket/--direct must be stripped, payload must be exact);
  * offline ``--direct`` fail-closed behavior (exit 70, no DB writes).

Nothing here starts researchctld and nothing opens a database: the Unix
socket is faked and every CLI invocation uses a throwaway ``--root`` whose
directory is asserted to stay empty.
"""

from __future__ import annotations

import io
import json
import sys
import tempfile
from contextlib import redirect_stderr, redirect_stdout
from pathlib import Path
from typing import Any, Callable

import synthetic_harness as harness

harness.install()

from app_v2.p5_infra import researchctl  # noqa: E402
from app_v2.p5_infra.authority_store import (  # noqa: E402
    AMENDMENT_A_SHA256,
    AMENDMENT_B_SHA256,
    AMENDMENT_C_SHA256,
)
from app_v2.p5_infra.research_db import FailClosed  # noqa: E402

D_HASH = "d" * 64  # parser-level tests never validate hashes against pins

PASSED: list[str] = []
FAILED: list[tuple[str, str]] = []
TESTS: list[tuple[str, Callable[[], None]]] = []


def test(fn: Callable[[], None]) -> Callable[[], None]:
    TESTS.append((fn.__name__, fn))
    return fn


def parse(argv: list[str]) -> Any:
    return researchctl.parser().parse_args(argv)


def expect_system_exit(code: int, fn: Callable[[], Any]) -> None:
    try:
        fn()
    except SystemExit as exc:
        assert exc.code == code, f"expected SystemExit({code}), got SystemExit({exc.code})"
        return
    raise AssertionError(f"expected SystemExit({code})")


def parse_rejected(argv: list[str], code: int = 2) -> None:
    with redirect_stderr(io.StringIO()):
        expect_system_exit(code, lambda: parse(argv))


# --------------------------------------------------------------------------
# direct C/D subcommand: parsing and choices
# --------------------------------------------------------------------------

@test
def direct_c_and_d_parse() -> None:
    for amendment_id, digest in (("C", AMENDMENT_C_SHA256), ("D", D_HASH)):
        args = parse([
            "amendment-register-direct",
            "--amendment-id", amendment_id,
            "--amendment-sha256", digest,
            "--producer-session-id", "producer-session",
        ])
        assert args.command == "amendment-register-direct"
        assert args.amendment_id == amendment_id
        assert args.amendment_sha256 == digest
        assert args.producer_session_id == "producer-session"
        assert args.direct is False


@test
def direct_rejects_a_and_b() -> None:
    for bad in ("A", "B"):
        parse_rejected([
            "amendment-register-direct",
            "--amendment-id", bad,
            "--amendment-sha256", AMENDMENT_C_SHA256,
            "--producer-session-id", "producer-session",
        ])


@test
def direct_requires_all_three_fields() -> None:
    parse_rejected(["amendment-register-direct", "--amendment-id", "C",
                    "--producer-session-id", "p"])
    parse_rejected(["amendment-register-direct", "--amendment-id", "C",
                    "--amendment-sha256", AMENDMENT_C_SHA256])
    parse_rejected(["amendment-register-direct",
                    "--amendment-sha256", AMENDMENT_C_SHA256,
                    "--producer-session-id", "p"])
    parse_rejected(["amendment-register-direct"])


# --------------------------------------------------------------------------
# delegated A/B subcommand: parsing and choices
# --------------------------------------------------------------------------

@test
def delegated_accepts_a_and_b_only() -> None:
    for amendment_id, digest in (("A", AMENDMENT_A_SHA256), ("B", AMENDMENT_B_SHA256)):
        args = parse([
            "amendment-register",
            "--delegation-id", "root-delegation-1",
            "--amendment-id", amendment_id,
            "--amendment-sha256", digest,
        ])
        assert args.command == "amendment-register"
        assert args.delegation_id == "root-delegation-1"
        assert args.amendment_id == amendment_id
        assert args.amendment_sha256 == digest


@test
def delegated_rejects_c_and_d() -> None:
    for bad in ("C", "D"):
        parse_rejected([
            "amendment-register",
            "--delegation-id", "root-delegation-1",
            "--amendment-id", bad,
            "--amendment-sha256", AMENDMENT_C_SHA256,
        ])


@test
def delegated_requires_delegation_id_and_hash() -> None:
    parse_rejected(["amendment-register", "--amendment-id", "A",
                    "--amendment-sha256", AMENDMENT_A_SHA256])
    parse_rejected(["amendment-register", "--delegation-id", "root-1",
                    "--amendment-id", "A"])


@test
def help_lists_both_amendment_commands() -> None:
    out = io.StringIO()
    with redirect_stdout(out):
        expect_system_exit(0, lambda: parse(["--help"]))
    text = out.getvalue()
    assert "amendment-register" in text
    assert "amendment-register-direct" in text


# --------------------------------------------------------------------------
# wire format produced by daemon_request (socket is faked)
# --------------------------------------------------------------------------

class FakeStream:
    def __init__(self, data: bytes) -> None:
        self.data = data

    def readline(self, size: int = -1) -> bytes:
        return self.data


class FakeSocket:
    def __init__(self, response: bytes) -> None:
        self.response = response
        self.sent = b""
        self.addr: str | None = None

    def __enter__(self) -> "FakeSocket":
        return self

    def __exit__(self, *exc: object) -> bool:
        return False

    def settimeout(self, value: float) -> None:
        pass

    def connect(self, addr: str) -> None:
        self.addr = addr

    def sendall(self, data: bytes) -> None:
        self.sent += data

    def makefile(self, mode: str) -> FakeStream:
        return FakeStream(self.response)


def wire_request(
    argv: list[str],
    response: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], FakeSocket]:
    import types

    fake = FakeSocket(json.dumps(response).encode("utf-8") + b"\n")
    fake_socket_module = types.ModuleType("socket")
    fake_socket_module.AF_UNIX = 1
    fake_socket_module.SOCK_STREAM = 2
    fake_socket_module.socket = lambda *a, **k: fake
    original = researchctl.socket
    researchctl.socket = fake_socket_module
    try:
        result = researchctl.daemon_request(parse(argv))
    finally:
        researchctl.socket = original
    request = json.loads(fake.sent.decode("utf-8"))
    return request, result, fake


@test
def direct_c_wire_payload_is_exact() -> None:
    request, result, fake = wire_request(
        [
            "--socket", "/tmp/ctl.sock",
            "amendment-register-direct",
            "--amendment-id", "C",
            "--amendment-sha256", AMENDMENT_C_SHA256,
            "--producer-session-id", "producer-session",
        ],
        {"ok": True, "result": {"status": "PASS", "amendment_id": "C"}, "peer_uid": 9001},
    )
    assert request == {
        "command": "amendment-register-direct",
        "amendment_id": "C",
        "amendment_sha256": AMENDMENT_C_SHA256,
        "producer_session_id": "producer-session",
    }, request
    assert fake.sent.endswith(b"\n")
    assert fake.addr == "/tmp/ctl.sock"
    assert result["writer_gateway"] == "researchctld"
    assert result["authenticated_peer_uid"] == 9001


@test
def direct_d_wire_payload_is_exact() -> None:
    request, _result, _fake = wire_request(
        [
            "amendment-register-direct",
            "--amendment-id", "D",
            "--amendment-sha256", D_HASH,
            "--producer-session-id", "producer-session",
        ],
        {"ok": True, "result": {"status": "PASS", "amendment_id": "D"}, "peer_uid": 9001},
    )
    assert request == {
        "command": "amendment-register-direct",
        "amendment_id": "D",
        "amendment_sha256": D_HASH,
        "producer_session_id": "producer-session",
    }, request


@test
def delegated_a_wire_payload_is_exact() -> None:
    request, _result, _fake = wire_request(
        [
            "amendment-register",
            "--delegation-id", "root-delegation-1",
            "--amendment-id", "A",
